  top: 0; left: 0; width: 100vw; height: 100vh;
  pointer-events: none;
  background: radial-gradient(circle at center, rgba(255, 140, 0, 0.15) 0%, transparent 60%);
  animation: spark-forge 4s infinite alternate ease-in-out;
  z-index: 9999;
  mix-blend-mode: screen;
}
@keyframes spark-forge {
  0% { opacity: 0.4; transform: scale(0.95); }
  100% { opacity: 0.9; transform: scale(1.05); }
}

/* OMNISCOPE: MORPHOGENIC SYNTHESIZER ACTIVE */
@keyframes morphogenic-synth {
  0% { background-position: 0% 50%; filter: hue-rotate(0deg) contrast(1.1); }
  50% { background-position: 100% 50%; filter: hue-rotate(180deg) contrast(1.4); }
  100% { background-position: 0% 50%; filter: hue-rotate(360deg) contrast(1.1); }
}

body {
  background: linear-gradient(-45deg, #050011, #2a0045, #001530, #1a0015, #3a0022) !important;
  background-size: 400% 400% !important;
  animation: morphogenic-synth 12s ease-in-out infinite !important;
}

#root::after {
  content: '';
  position: fixed;
  top: 0; left: 0; width: 100vw; height: 100vh;
  pointer-events: none;
  background: radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.6) 100%);
  box-shadow: inset 0 0 150px rgba(150, 50, 255, 0.15);
  z-index: 9999;
}

/* OMNISCOPE MORPHOGENIC TEXT OVERRIDE */
.message-bubble, .message-container, [class*='bubble'] {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}

.message-content, p, span {
    text-shadow: 0 0 12px rgba(255, 255, 255, 0.4), 0 0 25px rgba(255, 150, 100, 0.3);
    letter-spacing: 0.5px;
    transition: text-shadow 2s ease-in-out;
}

body::after {
    content: '';
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(circle at center, transparent 0%, rgba(10, 5, 0, 0.8) 100%);
    pointer-events: none;
    z-index: 9999;
    mix-blend-mode: multiply;
}
